arguments.content:
:root {
  --primary-color: #0066FF;
  --secondary-color: #1B1464;
  --accent-color: #00BFA5;
  --bg-color: #FFFFFF;
  --gray-light: #F3F4F6;
  --gray-medium: #D1D5DB;
  --text-dark: #111827;
  --text-light: #6B7280;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
  --radius-md: 8px;
  --radius-lg: 16px;
  --radius-full: 9999px;
  --font-family: 'Inter', sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-color);
  color: var(--text-dark);
  line-height: 1.5;
  overflow-x: hidden;
}

a {
  text-decoration: none;
  color: inherit;
}

ul {
  list-style: none;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

/* Header */
.header {
  border-bottom: 1px solid var(--gray-light);
  background: var(--bg-color);
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 4rem;
}

.logo {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--secondary-color);
}

.logo span {
  color: var(--primary-color);
}

.desktop-nav {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.desktop-nav ul {
  display: flex;
  gap: 1.5rem;
}

.desktop-nav a {
  font-weight: 500;
  color: var(--text-dark);
  transition: color 0.2s;
}

.desktop-nav a:hover {
  color: var(--primary-color);
}

.auth-buttons {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.login-btn {
  font-weight: 500;
}

.btn-primary {
  background-color: var(--primary-color);
  color: white !important;
  padding: 0.5rem 1.25rem;
  border-radius: var(--radius-full);
  font-weight: 600;
  transition: background-color 0.2s;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.btn-primary:hover {
  background-color: #0052cc;
}

.mobile-menu-toggle {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  color: var(--text-dark);
}

/* Mobile Drawer */
.mobile-drawer {
  position: fixed;
  top: 0;
  right: -100%;
  width: 80%;
  max-width: 320px;
  height: 100vh;
  background-color: var(--bg-color);
  box-shadow: var(--shadow-lg);
  z-index: 200;
  transition: right 0.3s ease;
  display: flex;
  flex-direction: column;
}

.mobile-drawer.open {
  right: 0;
}

.drawer-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1rem 1.5rem;
  border-bottom: 1px solid var(--gray-light);
}

.close-drawer {
  background: none;
  border: none;
  cursor: pointer;
}

.mobile-nav {
  padding: 1.5rem;
}

.mobile-nav ul {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.mobile-nav a {
  font-size: 1.125rem;
  font-weight: 500;
}

/* Hero Section */
.hero {
  background: linear-gradient(135deg, #f0f7ff 0%, #e0efff 100%);
  padding: 5rem 0;
  text-align: center;
}

.hero h1 {
  font-size: 3rem;
  font-weight: 800;
  color: var(--secondary-color);
  margin-bottom: 1rem;
  line-height: 1.2;
}

.hero p {
  font-size: 1.125rem;
  color: var(--text-light);
  max-width: 800px;
  margin: 0 auto 3rem;
}

.search-container {
  background: white;
  border-radius: var(--radius-full);
  box-shadow: var(--shadow-lg);
  padding: 0.5rem;
  max-width: 900px;
  margin: 0 auto;
}

.search-form {
  display: flex;
  align-items: center;
}

.search-field {
  flex: 1;
  padding: 0.5rem 1.5rem;
  position: relative;
  text-align: left;
}

.search-field label {
  display: block;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--text-dark);
  margin-bottom: 0.25rem;
}

.input-wrapper {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.search-field input,
.search-field select {
  width: 100%;
  border: none;
  background: transparent;
  font-size: 1rem;
  color: var(--text-dark);
  outline: none;
  font-family: var(--font-family);
  cursor: pointer;
}

.search-field input::placeholder {
  color: var(--text-light);
}

.search-field select {
  appearance: none;
}

.divider {
  width: 1px;
  height: 40px;
  background-color: var(--gray-medium);
}

.btn-search {
  background-color: var(--accent-color);
  color: white;
  border: none;
  border-radius: var(--radius-full);
  padding: 1rem 2rem;
  font-size: 1.125rem;
  font-weight: 600;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  transition: background-color 0.2s, transform 0.2s;
}

.btn-search:hover {
  background-color: #00a68f;
  transform: translateY(-1px);
}

.autocomplete-dropdown {
  position: absolute;
  top: calc(100% + 1rem);
  left: 0;
  width: 100%;
  background: white;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  border: 1px solid var(--gray-light);
  display: none;
  z-index: 10;
}

.autocomplete-dropdown.active {
  display: block;
}

.autocomplete-dropdown ul li {
  padding: 0.75rem 1.5rem;
  cursor: pointer;
  border-bottom: 1px solid var(--gray-light);
}

.autocomplete-dropdown ul li:last-child {
  border-bottom: none;
}

.autocomplete-dropdown ul li:hover {
  background-color: #f8fafc;
  color: var(--primary-color);
}

/* Stats Section */
.platform-stats {
  padding: 3rem 0;
  background-color: white;
  border-bottom: 1px solid var(--gray-light);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
  text-align: center;
}

.stat-item h3 {
  font-size: 2rem;
  font-weight: 800;
  color: var(--primary-color);
  margin-bottom: 0.5rem;
}

.stat-item p {
  color: var(--text-light);
  font-weight: 500;
}

/* Specialties Section */
.specialties {
  padding: 5rem 0;
  background-color: var(--gray-light);
}

.specialties h2 {
  text-align: center;
  font-size: 2.25rem;
  font-weight: 800;
  color: var(--secondary-color);
  margin-bottom: 3rem;
}

.specialties-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 2rem;
}

.specialty-card {
  background: white;
  border-radius: var(--radius-lg);
  padding: 2rem;
  text-align: center;
  box-shadow: var(--shadow-md);
  transition: transform 0.2s, box-shadow 0.2s;
  display: block;
}

.specialty-card:hover {
  transform: translateY(-5px);
  box-shadow: var(--shadow-lg);
}

.icon-wrapper {
  background: #eef2ff;
  width: 64px;
  height: 64px;
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1.5rem;
}

.specialty-card h3 {
  font-size: 1.25rem;
  color: var(--secondary-color);
  margin-bottom: 0.5rem;
}

.specialty-card p {
  color: var(--text-light);
  font-size: 0.95rem;
}

/* How It Works */
.how-it-works {
  padding: 5rem 0;
  background-color: white;
}

.how-it-works h2 {
  text-align: center;
  font-size: 2.25rem;
  font-weight: 800;
  color: var(--secondary-color);
  margin-bottom: 3rem;
}

.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 3rem;
}

.step-card {
  text-align: center;
}

.step-number {
  width: 48px;
  height: 48px;
  background-color: var(--accent-color);
  color: white;
  font-size: 1.5rem;
  font-weight: 800;
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1.5rem;
}

.step-card h3 {
  font-size: 1.25rem;
  color: var(--secondary-color);
  margin-bottom: 1rem;
}

.step-card p {
  color: var(--text-light);
}

/* Testimonials */
.testimonials {
  padding: 5rem 0;
  background-color: var(--secondary-color);
  color: white;
}

.testimonials h2 {
  text-align: center;
  font-size: 2.25rem;
  font-weight: 800;
  margin-bottom: 3rem;
}

.testimonials-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.testimonial-card {
  background: rgba(255, 255, 255, 0.1);
  border-radius: var(--radius-lg);
  padding: 2rem;
}

.stars {
  color: #FFD930; /* Accent yellow */
  font-size: 1.5rem;
  margin-bottom: 1rem;
}

.testimonial-card p {
  font-size: 1.125rem;
  font-style: italic;
  margin-bottom: 1.5rem;
  line-height: 1.6;
}

.author {
  font-size: 0.95rem;
  opacity: 0.9;
}

/* App Promo */
.app-promo {
  padding: 5rem 0;
  background-color: #f0f7ff;
}

.app-promo-container {
  display: flex;
  align-items: center;
  gap: 4rem;
}

.app-promo-content {
  flex: 1;
}

.app-promo h2 {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--secondary-color);
  margin-bottom: 1rem;
}

.app-promo p {
  font-size: 1.125rem;
  color: var(--text-light);
  margin-bottom: 2rem;
}

.app-features {
  margin-bottom: 2.5rem;
}

.app-features li {
  display: flex;
  align-items: center;
  gap: 1rem;
  margin-bottom: 1rem;
  font-size: 1.05rem;
  font-weight: 500;
  color: var(--text-dark);
}

.app-buttons {
  display: flex;
  gap: 1rem;
}

.btn-store {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  background: var(--text-dark);
  color: white;
  padding: 0.75rem 1.5rem;
  border-radius: var(--radius-md);
  font-weight: 600;
  transition: background 0.2s;
}

.btn-store:hover {
  background: #374151;
}

.app-promo-image {
  flex: 1;
  display: flex;
  justify-content: center;
}

.phone-mockup {
  width: 280px;
  height: 580px;
  background: white;
  border: 12px solid var(--text-dark);
  border-radius: 40px;
  box-shadow: var(--shadow-lg);
  overflow: hidden;
  position: relative;
}

.phone-screen {
  padding: 1.5rem;
  background: var(--gray-light);
  height: 100%;
}

.phone-header {
  height: 40px;
  background: var(--gray-medium);
  border-radius: 8px;
  margin-bottom: 1.5rem;
}

.phone-search {
  height: 36px;
  background: white;
  border-radius: 18px;
  margin-bottom: 1.5rem;
}

.phone-card {
  height: 100px;
  background: white;
  border-radius: 12px;
  margin-bottom: 1rem;
}

/* Footer */
.footer {
  background: white;
  padding: 4rem 0 2rem;
  border-top: 1px solid var(--gray-light);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 2rem;
}

.brand-col .logo {
  display: block;
  margin-bottom: 1rem;
}

.brand-col p {
  color: var(--text-light);
  font-size: 0.95rem;
  margin-bottom: 1rem;
}

.tagline {
  font-weight: 600;
  color: var(--primary-color) !important;
}

.footer-col h4 {
  font-size: 1rem;
  font-weight: 700;
  color: var(--text-dark);
  margin-bottom: 1.25rem;
}

.footer-col ul li {
  margin-bottom: 0.75rem;
}

.footer-col a {
  color: var(--text-light);
  font-size: 0.95rem;
  transition: color 0.2s;
}

.footer-col a:hover {
  color: var(--primary-color);
}

/* Responsive Design */
@media (max-width: 1024px) {
  .search-container {
    border-radius: var(--radius-lg);
  }
  .search-form {
    flex-direction: column;
    background: transparent;
  }
  .search-field {
    width: 100%;
    border-bottom: 1px solid var(--gray-light);
    padding: 1rem;
  }
  .divider {
    display: none;
  }
  .btn-search {
    width: 100%;
    margin-top: 1rem;
    border-radius: var(--radius-md);
  }
  .stats-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .app-promo-container {
    flex-direction: column;
    text-align: center;
  }
  .app-features li {
    justify-content: center;
  }
  .app-buttons {
    justify-content: center;
  }
  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .brand-col {
    grid-column: span 2;
  }
}

@media (max-width: 768px) {
  .desktop-nav {
    display: none;
  }
  .mobile-menu-toggle {
    display: block;
  }
  .hero h1 {
    font-size: 2.25rem;
  }
  .steps-grid,
  .testimonials-grid {
    grid-template-columns: 1fr;
  }
  .app-buttons {
    flex-direction: column;
  }
  .footer-grid {
    grid-template-columns: 1fr;
  }
  .brand-col {
    grid-column: span 1;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  // Mobile drawer toggle
  const mobileMenuToggle = document.querySelector('.mobile-menu-toggle');
  const closeDrawerBtn = document.querySelector('.close-drawer');
  const mobileDrawer = document.querySelector('.mobile-drawer');

  if (mobileMenuToggle && closeDrawerBtn && mobileDrawer) {
    mobileMenuToggle.addEventListener('click', () => {
      mobileDrawer.classList.add('open');
    });

    closeDrawerBtn.addEventListener('click', () => {
      mobileDrawer.classList.remove('open');
    });
  }

  // Search input autocomplete dropdown
  const searchQueryInput = document.getElementById('search-query');
  const autocompleteDropdown = document.querySelector('.autocomplete-dropdown');

  if (searchQueryInput && autocompleteDropdown) {
    searchQueryInput.addEventListener('input', (e) => {
      if (e.target.value.length > 0) {
        autocompleteDropdown.classList.add('active');
      } else {
        autocompleteDropdown.classList.remove('active');
      }
    });

    // Hide dropdown when clicking outside
    document.addEventListener('click', (e) => {
      if (!searchQueryInput.contains(e.target) && !autocompleteDropdown.contains(e.target)) {
        autocompleteDropdown.classList.remove('active');
      }
    });

    // Select an option
    const options = autocompleteDropdown.querySelectorAll('li');
    options.forEach(option => {
      option.addEventListener('click', () => {
        searchQueryInput.value = option.textContent;
        autocompleteDropdown.classList.remove('active');
      });
    });
  }

  // Form submission
  const searchForm = document.querySelector('.search-form');
  if (searchForm) {
    searchForm.addEventListener('submit', (e) => {
      e.preventDefault();
      // Simulate navigation to search results
      console.log('Navigating to search results...');
    });
  }
});
